public class Main {
    static String[] todos = new String[3];
    static int jumlah = 0;

    public static void main(String[] args) {
        tambah("Belajar Java");
        tambah("");
        System.out.println("Jumlah: " + jumlah);
        tambah("   ");
        System.out.println("Jumlah: " + jumlah);
        tambah("Cuci motor");
        tambah("Bayar listrik");
        tambah("Masak");
        System.out.println("Jumlah: " + jumlah);
        tambah("Cuci motor");
    }

    static void tambah(String isi) {
        if (isi.trim().isEmpty()) {
            System.out.println("Todo tidak boleh kosong");
            return;
        }
        if (sudahAda(isi)) {
            System.out.println("Todo sudah ada");
            return;
        }
        if (jumlah >= todos.length) {
            System.out.println("Todolist penuh");
            return;
        }
        todos[jumlah] = isi;
        jumlah++;
    }

    static boolean sudahAda(String isi) {
        for (int i = 0; i < jumlah; i++) {
            if (todos[i].equals(isi)) {
                return true;
            }
        }
        return false;
    }
}

public class Main {
    static String[] todos = new String[5];
    static int jumlah = 0;

    public static void main(String[] args) {
        tambah("Belajar Java");
        tambah("");
        System.out.println("Jumlah: " + jumlah);
        tambah("   ");
        System.out.println("Jumlah: " + jumlah);
        tambah("Cuci motor");
        tambah("Bayar listrik");
        tambah("Masak");
        System.out.println("Jumlah: " + jumlah);
        tambah("Cuci motor");
        tambah("  Senam  ");
        System.out.println("Terakhir: [" + todos[jumlah - 1] + "]");
    }

    static void tambah(String isi) {
        if (isi.trim().isEmpty()) {
            System.out.println("Todo tidak boleh kosong");
            return;
        }
        if (sudahAda(isi)) {
            System.out.println("Todo sudah ada");
            return;
        }
        if (jumlah >= todos.length) {
            System.out.println("Todolist penuh");
            return;
        }
        todos[jumlah] = isi.trim();
        jumlah++;
    }

    static boolean sudahAda(String isi) {
        for (int i = 0; i < jumlah; i++) {
            if (todos[i].equals(isi)) {
                return true;
            }
        }
        return false;
    }
}

